	"com/westernacher/collaborationPortal/core/fragment/sections/ResourceSection.fragment.xml":'<core:FragmentDefinition xmlns:core="sap.ui.core" xmlns="sap.m" xmlns:t="sap.ui.table" xmlns:f="sap.ui.layout.form"\n\txmlns:smartField="sap.ui.comp.smartfield"><Table inset="false" id="idResourceTable"\n\t\titems="{ path: \'to_Items\', filters: [{path:\'TranspOrdItemCategory\', operator:\'EQ\', value1:\'AVR\'}]}"\n\t\tclass="tablesborder sapUiMediumMarginTop" backgroundDesign="Solid"><headerToolbar><Toolbar design="Solid"><Title text="{i18nhome>Resource}"/></Toolbar></headerToolbar><columns><Column minScreenWidth="Small" width="12em" hAlign="Begin" demandPopin="true"><Text text="{to_Items/PlateNumber/#@sap:label}"/></Column><Column minScreenWidth="Tablet" width="6em" hAlign="Begin" demandPopin="true"><Text text="{to_Items/Country/#@sap:label}"/></Column><Column minScreenWidth="Tablet" width="4em" hAlign="End" demandPopin="true"><Text text="{i18nhome>Action}"/></Column></columns><items><ColumnListItem><cells><Text text="{PlateNumber}" wrapping="true"/><Text text="{Country}"/><OverflowToolbar class="noborders sapUiNoMarginBottom"><ToolbarSpacer/><Button icon="sap-icon://edit" press="onUpdateResourceButtonPress" type="Transparent" tooltip="{i18n>resourceEditTooltip}"\n\t\t\t\t\t\t\tenabled="{_AM>/E_AEditItem}" visible="{_AM>/V_AEditItem}"/></OverflowToolbar></cells></ColumnListItem></items></Table></core:FragmentDefinition>',
