	"com/westernacher/collaborationPortal/core/modules/confirmation/i18n/i18n.properties":'# This is the resource bundle for Westernacher Collaboration Portal\n\n#XTIT: Application name\nappTitle=Freight Orders Confirmation\n\n#YDES: Application description\nappDescription=Freight Orders Confirmation Module of Westernacher Collaboration Portal\n\n\nFONumberLabel =Freight Order Number: \n\n#XFLD: Home label\nhomeLink = Home\n#XFLD: Fright Order Confirmation list\nFOConfirmList = Freight Order Confirmation List\n\n#XTIT: General Info title\ngeneralInfoOP = General Info\n#XTIT: Pickup Info title\npickupInfoOP = Pickup Info\n#XTIT: Delivery Info title\ndeliveryInfoOP = Delivery Info\n\n#~~~~~~~~~~~~~ Table Filter buttons ~~~~~~~~\n#XBUT: All\nallBtn = All\n#XBUT: In Confirmation\ninConfirmationBtn = In Confirmation\n#XBUT: Confirmed\nconfirmedBtn = Confirmed\n#XBUT: Accept\nacceptBtn = Accept\n#XBUT: Reject\nrejectBtn = Reject\n#XBUT: Upload Attachments\nuploadAttachmentsBtn = Upload Attachments\n#XBUT: Set to Complete\nsetToCompleteBtn = Set to Complete\n#XBUT: Set to Cancel\nsetToCancelBtn = Set to Cancel\n\n#~~~ Worklist View ~~~~~~~~~~~~~~~~~~~~~~~~~~\n#XTIT: Worklist view title\nworklistViewTitle=Manage <LanguagesCollectionPlural>\n#XTIT: Table header\ntableHeaderText = Freight Orders\n\n#XTIT: Worklist page title\nworklistTitle=Westernacher Collaboration Portal\n\n#XTIT: Table view title\nworklistTableTitle=<LanguagesCollectionPlural>\n\n#XTOL: Tooltip for the search field\nworklistSearchTooltip=Enter an <LanguagesCollection> name or a part of it.\n\n#XBLI: text for a table with no data with filter or search\nworklistNoDataWithSearchText=No matching <LanguagesCollectionPlural> found\n\n#XTIT: Table view title with placeholder for the number of items\nworklistTableTitleCount=<LanguagesCollection> ({0})\n\n#XTIT: The title of the column containing the ButtonText of LanguagesCollection\ntableNameColumnTitle=<ButtonText>\n\n\n#XBLI: text for a table with no data\ntableNoDataText=No <LanguagesCollectionPlural> are currently available\n\n#XLNK: text for link in \'not found\' pages\nbackToWorklist=Show Westernacher Collaboration Portal\n\n#~~~ Object View ~~~~~~~~~~~~~~~~~~~~~~~~~~\n#XTIT: Object view title\nobjectViewTitle=<LanguagesCollection> Details\n\n#XTIT: Object page title\nobjectTitle=<LanguagesCollection>\n\n\n#XTIT: Label for the ButtonText\nButtonTextLabel=ButtonText\n\n\n#~~~ Share Menu Options ~~~~~~~~~~~~~~~~~~~~~~~\n\n#XTIT: Send E-Mail subject\nshareSendEmailWorklistSubject=<Email subject PLEASE REPLACE ACCORDING TO YOUR USE CASE>\n\n#YMSG: Send E-Mail message\nshareSendEmailWorklistMessage=<Email body PLEASE REPLACE ACCORDING TO YOUR USE CASE>\\r\\n{0}\n\n#XTIT: Send E-Mail subject\nshareSendEmailObjectSubject=<Email subject including object identifier PLEASE REPLACE ACCORDING TO YOUR USE CASE> {0}\n\n#YMSG: Send E-Mail message\nshareSendEmailObjectMessage=<Email body PLEASE REPLACE ACCORDING TO YOUR USE CASE> {0} (id: {1})\\r\\n{2}\n\n#~~~~~~~~~~~ Icon Tooltips ~~~~~~~~~~~~\n#XMSG: status tooltip\nconfirmationStatus = Status\n#XMSG: Dangerous Goods\ndangerousGoods = Not Dangerous Good\n\n#~~~~~ Object Section Icon Tooltips\n#XBUT: Cargo item table edit button\ncargoItemEditTooltip = Edit\n#XBUT: Dangerous good icon\ndangerousGoodsTooltip = Not Dangerous Good\n#XBUT: Stackable icon\nstackableGoodTooltip = Stackable Good\n#XBUT: Resource table edit icon\nresourceEditTooltip = Edit\n#XBUT: Attachments upload icon\nattachmentUploadTooltip = Upload Attachments\n#XBUT: Attachments delete icon\nattachmentDeleteTooltip = Delete\n\n#~~~ Not Found View ~~~~~~~~~~~~~~~~~~~~~~~\n\n#XTIT: Not found view title\nnotFoundTitle=Not Found\n\n#YMSG: The LanguagesCollection not found text is displayed when there is no LanguagesCollection with this id\nnoObjectFoundText=This <LanguagesCollection> is not available\n\n#YMSG: The LanguagesCollection not available text is displayed when there is no data when starting the app\nnoObjectsAvailableText=No <LanguagesCollectionPlural> are currently available\n\n#YMSG: The not found text is displayed when there was an error loading the resource (404 error)\nnotFoundText=The requested resource was not found\n\n#~~~ Error Handling ~~~~~~~~~~~~~~~~~~~~~~~\n\n#YMSG: Error dialog description\nerrorText=Sorry, a technical error occurred! Please try again later.\n\nChangeRole=Change Role\nFONumber=FO Number\nTransportationModeDesc=Transportation Mode\nPickupLocation=Pickup Location\nPlannedPickupDate=Planned Pickup Date\nConfirmedPickupTime=Confirmed Pickup Time\n\nDeliveryLocation=Delivery Location\nPlannedDeliveryTime=Planned Delivery Time\nConfirmedDeliveryTime=Confirmed Delivery Time\nTOCategory=TOCategory\nTOType=TO Type\nSourceLocation=Source Location\nDestinationLocation=Destination Location\nMeansOFTransport=Means of Transport\nModeOfTransport=Mode of Transport\nShipper=Shipper\nConsignee=Consignee\nAcceptFO=Accept FO\nUpdateFO=Update Freight Order\nDangerousGood=Dangerous Good\nAddress=Address\nAccept=Accept\nReject=Reject\n\nUpdateConfirmedDatesSuccessMessage=Confirmed Dates updated successfully!\nUpdateConfirmedDatesErrorMessage=Confirmed Dates could not be updated!\nFreightOrdersInConfirmation=Freight Orders In Confirmation\n\n# ~~~~~~~~~~~~Cargo Tree Table ~~~~~~\nCargoItems=Cargo Items\nSubmitChanges=Submit Changes\nLocation=Location\nStartDateTime=Start Date/Time\nEndDateTime=End Date/Time\nActivity=Activity\nGrossWeight=Gross Weight\nGrossVolume=Gross Volume\nQuantity=Quantity\nActualQuantity=Actual Quantity\nDangerousGoods= Dangerous Goods\nLoad=Load\nUnload=Unload\n',
